import{_ as n}from"./bolt-90ed8319.js";import{_ as o}from"./eye-bd28630a.js";import{_ as s}from"./shield-alert-226df5e9.js";import{_ as i,X as d,n as h,p as c,q as l,a9 as u,H as p,w as g,t as e,y as t}from"./framework-0e2f11f3.js";const f={};function m(x,a){const r=d("WhatsNext");return h(),c("div",null,[l(" markdownlint-disable MD029 MD024 MD036 MD033 "),a[1]||(a[1]=u('<h1 id="securechain-portal-and-cli" tabindex="-1"><a class="header-anchor" href="#securechain-portal-and-cli" aria-hidden="true" tabindex="-1">#</a> SecureChain Portal and CLI</h1><div class="tip custom-block"><p class="custom-block-title">Documentation</p><p>The complete documentation of the portal and the CLI — getting started, every page and command, CI setup, administration — is the <strong><a href="https://sc.tuxcare.cloud/guide" target="_blank" rel="noopener noreferrer">SecureChain user guide</a></strong>. It is maintained together with the product and is the source of truth. This page is a short overview.</p></div><p>SecureChain has two tools you work with. The <strong>portal</strong> is the web application where your organization has a private workspace. The <strong>CLI</strong> is the <code>securechain</code> command that runs on a developer machine and in CI. The CLI sends the dependencies of a project to the workspace, the portal shows what is vulnerable and what to fix first, and the CLI moves the project to the TuxCare builds.</p><h2 id="the-portal" tabindex="-1"><a class="header-anchor" href="#the-portal" aria-hidden="true" tabindex="-1">#</a> The Portal</h2><p>Your workspace in the portal — for example <code>name.sc.tuxcare.cloud</code> — keeps the dependencies of every repository and container image you send, matches them with the advisory data and the TuxCare catalogue, and keeps the result current:</p><ul><li><strong>What do we ship?</strong> Every scan is kept, so the dependencies of every repository, branch and image are in one place, with their changes from scan to scan.</li><li><strong>What is vulnerable now?</strong> The matching runs in the portal. When a new advisory comes out, every stored scan is checked again — you learn about a new finding without a new scan.</li><li><strong>What first?</strong> Grades, known-exploited findings, fix deadlines and the CRA clocks order the findings, and the fix plan names the TuxCare build that fixes each one.</li><li><strong>Who does what?</strong> Triage states, departments, roles, alerts by email, Slack and webhook, and the audit log make the work of a team visible.</li><li><strong>How do programs get in?</strong> Access tokens for the CLI and CI, the REST API for scripts and dashboards, and the MCP server for AI assistants.</li></ul><p>Guide: <strong><a href="https://sc.tuxcare.cloud/guide/portal" target="_blank" rel="noopener noreferrer">The portal</a></strong>.</p><h2 id="the-cli" tabindex="-1"><a class="header-anchor" href="#the-cli" aria-hidden="true" tabindex="-1">#</a> The CLI</h2><p><code>securechain</code> is one static binary for Linux, macOS and Windows (x86-64 and ARM64) that runs on a developer machine and in a CI job. It sends the dependencies of a project to your workspace — never the source code — fails a build on the findings your policy names, and moves a project to the TuxCare builds, including transitive dependencies, then verifies the result. Every writing command has <code>--dry-run</code>, and a run that cannot verify its result restores every file it changed.</p><p>Guide: <strong><a href="https://sc.tuxcare.cloud/guide/developer" target="_blank" rel="noopener noreferrer">Developer start</a></strong>, <strong><a href="https://sc.tuxcare.cloud/guide/ci" target="_blank" rel="noopener noreferrer">CI start</a></strong>, <strong><a href="https://sc.tuxcare.cloud/guide/cli" target="_blank" rel="noopener noreferrer">The CLI and CI</a></strong>.</p><h2 id="whats-next" tabindex="-1"><a class="header-anchor" href="#whats-next" aria-hidden="true" tabindex="-1">#</a> What&#39;s Next?</h2>',11)),p(r,{"hide-title":""},{default:g(()=>a[0]||(a[0]=[e("ul",null,[e("li",null,[e("img",{src:n,alt:""}),t(),e("a",{href:"https://sc.tuxcare.cloud/guide",target:"_blank",rel:"noopener noreferrer"},"SecureChain user guide"),t(" — The complete documentation of the portal and the CLI")]),e("li",null,[e("img",{src:o,alt:""}),t(),e("a",{href:"https://tuxcare.com/cve-tracker/",target:"_blank",rel:"noopener noreferrer"},"CVE Tracker"),t(" — Track vulnerability fixes and updates")]),e("li",null,[e("img",{src:s,alt:""}),t(),e("a",{href:"https://security.tuxcare.com/vex/cyclonedx/",target:"_blank",rel:"noopener noreferrer"},"VEX feed"),t(" — Vulnerability Exploitability eXchange feed")])],-1)])),_:1,__:[0]})])}const _=i(f,[["render",m],["__file","index.html.vue"]]);export{_ as default};
